import{_ as l,c as a,o as s,al as t}from"./chunks/framework.D0eKsMgt.js";const c=JSON.parse('{"title":"错误码说明","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data/error_code.md","filePath":"docs/data/error_code.md"}'),e={name:"docs/data/error_code.md"};function r(o,i,n,h,p,d){return s(),a("div",null,i[0]||(i[0]=[t('<h1 id="错误码说明" tabindex="-1">错误码说明 <a class="header-anchor" href="#错误码说明" aria-label="Permalink to &quot;错误码说明&quot;">​</a></h1><p>本文档定义了系统中使用的错误码及其含义，便于开发人员快速定位和解决问题。</p><h2 id="错误码格式" tabindex="-1">错误码格式 <a class="header-anchor" href="#错误码格式" aria-label="Permalink to &quot;错误码格式&quot;">​</a></h2><p>所有错误码均为6位数字，按错误类型分组：</p><ul><li>100000-109999: 网络连接错误</li><li>110000-119999: API错误</li><li>120000-129999: 数据处理错误</li><li>130000-139999: 系统错误</li></ul><h2 id="详细错误码列表" tabindex="-1">详细错误码列表 <a class="header-anchor" href="#详细错误码列表" aria-label="Permalink to &quot;详细错误码列表&quot;">​</a></h2><h3 id="网络连接错误-100000-109999" tabindex="-1">网络连接错误 (100000-109999) <a class="header-anchor" href="#网络连接错误-100000-109999" aria-label="Permalink to &quot;网络连接错误 (100000-109999)&quot;">​</a></h3><ul><li><p><strong>100001</strong>: 请求超时，请检查网络连接</p><ul><li>含义：API请求超过了设定的时间限制</li><li>可能原因：网络不稳定、服务器响应慢</li><li>解决方案：检查网络连接，稍后重试</li></ul></li><li><p><strong>100002</strong>: API请求被浏览器阻止，尝试使用代理重新请求</p><ul><li>含义：浏览器或浏览器扩展阻止了API请求</li><li>可能原因：广告拦截器、安全扩展拦截</li><li>解决方案：尝试禁用浏览器扩展或使用代理</li></ul></li><li><p><strong>100003</strong>: 无法连接到API服务器，可能是网络问题或浏览器扩展拦截</p><ul><li>含义：Chrome浏览器下无法建立API连接</li><li>可能原因：网络问题、浏览器扩展拦截</li><li>解决方案：检查网络连接、暂时禁用浏览器扩展、尝试使用其他浏览器</li></ul></li><li><p><strong>100004</strong>: 无法连接到API服务器，可能是网络问题或CORS限制</p><ul><li>含义：非Chrome浏览器下无法建立API连接</li><li>可能原因：网络问题、CORS配置问题</li><li>解决方案：确认API服务器已正确配置CORS、尝试使用代理服务器转发请求、检查浏览器安全策略</li></ul></li><li><p><strong>100005</strong>: 无法连接到API服务器，可能是网络问题或CORS限制</p><ul><li>含义：通用网络连接错误</li><li>可能原因：网络问题、服务器不可用</li><li>解决方案：检查网络连接，确认服务器正常运行</li></ul></li></ul><h3 id="api错误-110000-119999" tabindex="-1">API错误 (110000-119999) <a class="header-anchor" href="#api错误-110000-119999" aria-label="Permalink to &quot;API错误 (110000-119999)&quot;">​</a></h3><ul><li><p><strong>110001</strong>: API端点不存在，请检查API路径是否正确</p><ul><li>含义：请求的API路径不存在</li><li>可能原因：API路径错误、服务器配置问题</li><li>解决方案：检查API路径是否正确，确认服务器配置</li></ul></li><li><p><strong>110002</strong>: HTTP错误</p><ul><li>含义：服务器返回非2xx状态码</li><li>可能原因：服务器错误、权限问题</li><li>解决方案：检查服务器状态，确认请求参数和权限</li></ul></li><li><p><strong>110003</strong>: API错误</p><ul><li>含义：API返回了错误代码和消息</li><li>可能原因：请求参数错误、业务逻辑错误</li><li>解决方案：检查请求参数，参考API文档</li></ul></li></ul><h3 id="系统错误-130000-139999" tabindex="-1">系统错误 (130000-139999) <a class="header-anchor" href="#系统错误-130000-139999" aria-label="Permalink to &quot;系统错误 (130000-139999)&quot;">​</a></h3><ul><li><strong>130001</strong>: 未知错误 <ul><li>含义：未分类的错误</li><li>可能原因：系统bug、未预见的情况</li><li>解决方案：查看控制台日志获取详细信息，联系开发人员</li></ul></li></ul><h2 id="错误码使用方式" tabindex="-1">错误码使用方式 <a class="header-anchor" href="#错误码使用方式" aria-label="Permalink to &quot;错误码使用方式&quot;">​</a></h2><p>在代码中，错误码与错误信息对应使用，便于定位问题。例如：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 抛出错误码对应的错误</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`[110001] API端点不存在，请检查API路径是否正确`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="如何贡献" tabindex="-1">如何贡献 <a class="header-anchor" href="#如何贡献" aria-label="Permalink to &quot;如何贡献&quot;">​</a></h2><p>如果您发现新的错误类型需要添加错误码，请联系开发团队更新此文档。</p>',17)]))}const P=l(e,[["render",r]]);export{c as __pageData,P as default};
